def second_frequent(sequence):
    frequency = {}
    # Count the frequency of each element in the sequence
    for elt in sequence:
        if elt not in frequency:
            frequency[elt] = 1
        else:
            frequency[elt] += 1
    # Replace None with 0 if there's no second frequency element
    frequency = {k: v for k, v in frequency.items() if v is not None}
    # Sort the dictionary by frequency in descending order, and then by key in ascending order
    sorted_entries = sorted(zip(frequency.values(), frequency.keys()), reverse=True)
    # The second highest frequency (second most repeated string)
    return sorted_entries[1][1] if len(sorted_entries) > 1 else None
