    for row in triangle[1:]:
        for col in range(len(row)):
            if col == 0:
                # First element of the row
                row[col] += prev_row[col]
            elif col == len(row) - 1:
                # Last element of the row
                row[col] += prev_row[col - 1]
            else:
                # Inner elements
                row[col] += min(prev_row[col - 1], prev_row[col])
        prev_row = row
    return min(prev_row)
