def get_ludic(n: int) -> List[int]:
    # Initialize the list of lucid numbers
    ludic_numbers = []
    # Start from the first number greater than 1 that is prime
    number = 2
    while number <= n:
        # Check if the number is prime
        if is_prime(number):
            ludic_numbers.append(number)
        number += 1
