def is_prime(number: int) -> bool:
    # If the number is less than 2, it is not prime
    if number < 2:
        return False
    # Check divisibility from 2 to the square root of the number
    for i in range(2, int(number**0.5) + 1):
        if number % i == 0:
            return False
    return True
