def largest_subset(arr, N):
    mod = 1e9 + 7
    sums = [0] * N
    size = [1] * N

    # work bottom to top to fill the sums and sizes array
    for i in range(1, N):
        for j in range(i):
            if arr[j] % arr[i] == 0:
                if sums[j] + arr[i] > sums[i]:
                    sums[i] = sums[j] + arr[i]
                    size[i] = size[j] + 1

    # find the maximum size sum
    max_size = max(size)
    max_index = size.index(max_size)
    result = arr[max_index]

    # add all the numbers with the maximum size sum
    for i in range(max_index + 1, N):
        if max_size == size[i]:
            result += arr[i]
            result = result % mod

    return(int(result))
```

