def find_Sum(arr,n):
    # Initialize a dictionary to store the frequency of each element
    freq_dict = {}
    # Iterate over the array to populate the dictionary with frequencies
    for num in arr:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1
    # Initialize sum to 0
    sum = 0
    # Iterate over the array to add elements whose frequency is 1 to the sum
    for num in arr:
        if freq_dict[num] == 1:
            sum += num
    return sum
