    freq = {}
    pos = {}

    # Calculate frequency for each element
    for i in range(size):
        if arr[i] not in freq:
            freq[arr[i]] = 1
        else:
            freq[arr[i]] += 1
            pos[arr[i]] = i

    # Initialize variables to store the maximum and minimum frequencies and their positions
    max_freq = min_freq = 0
    max_pos = min_pos = None

    # Iterate through the frequency dictionary to find max and min frequencies and their positions
    for key in freq:
        if freq[key] > max_freq:
            max_freq = freq[key]
            max_pos = pos[key]
        if freq[key] < min_freq:
            min_freq = freq[key]
            min_pos = pos[key]

    # Calculate the difference between max and min frequencies
    return max_freq - min_freq
