def Sum(n):
    # Collect prime divisors of n
    prime_divisors = []
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            prime_divisors.append(i)
            n //= i
    if n > 2:
        prime_divisors.append(n)

    # Compute the sum of all prime divisors
    return sum(prime_divisors)
```

```python
def Sum(n):
    primes = {}
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            if i in primes:
                primes[i] += 1
            else:
                primes[i] = 1
            n //= i
    if n > 2:
        if n in primes:
            primes[n] += 1
        else:
            primes[n] = 1
    total = 1
    for val in primes.values():
        total *= (1 + val)
    return total
```

