def count_duplic(f):
    if len(f) < 2:
        return []

    result DUP = []
    result original = []

    for i in range(1, len(f)):
        if f[i] == f[i - 1]:
            DUP.append(f[i])
        else:
            original.append(-1)  # -1 to indicate the start of a new sequence
            DUP.append(f[i])

    original.append(-1)  # for the last sequence

    i = 0
    while i < len(original):
        if original[i] == -1:
            j = i + 1
            while j < len(original) and original[j] == original[i]:
                j += 1
            result.original.append(i + 1)
            result.DUP.append(j - i - 1)
            i = j
        else:
            i += 1

    return result
