def lcs_of_three(X, Y, Z, m, n, l):
    # Create a 2D array to store lengths of lcs of substring
    lengths = [[0 for _ in range(n+1)] for _ in range(l+1)]

    # Build the lengths array in bottom up manner
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, l+1):
                if X[i-1] == Y[j-1] and X[i-1] == Z[k-1]:
                    lengths[i][j][k] = lengths[i-1][j-1][k-1] + 1
                else:
                    lengths[i][j][k] = max(lengths[i-1][j][k], lengths[i][j-1][k], lengths[i][j][k-1])

    # The bottom-right cell contains the length of the lcs of X, Y, and Z
    return lengths[m][n][l]
```

