def lcs_of_three(s1, s2, s3, n1, n2, n3):
    dp = [[[0] * n3 for _ in range(n2)] for _ in range(n1)]

    for i in range(n1):
        for j in range(n2):
            for k in range(n3):
                if s1[i] == s2[j] == s3[k]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i-1][j][k-1], dp[i][j-1][k-1])

    return dp[n1-1][n2-1][n3-1]

