def modular_sum(nums, n, m):
    if sum(nums) % m == 0:
        return True
    visited = set()
    visited.add(0)
    def dfs(i, current_sum):
        if current_sum == m:
            return True
        if i == n or current_sum > m:
            return False
        if current_sum in visited:
            return False
        visited.add(current_sum)
        return dfs(i + 1, current_sum + nums[i]) or dfs(i + 1, current_sum)
    return dfs(0, 0)
```

