    for i in range(n+1):
        T[i][0] = True
    for i in range(m+1):
        T[0][i] = False

    # Fill the T table
    for i in range(1, n+1):
        for j in range(1, m+1):
            if arr[i-1] <= j:
                T[i][j] = T[i-1][j] or T[i-1][j-arr[i-1]]
            else:
                T[i][j] = T[i-1][j]

    # Check if a subset with sum divisible by m exists
    return T[n][m]
