    second: int

def max_chain_length(edges: List[Pair], number_of_pairs: int) -> int:
    start_time = 0
    end_time = 0
    dp = [[0] * (number_of_pairs + 1) for _ in range(number_of_pairs + 1)]

    for i in range(1, number_of_pairs + 1):
        for j in range(i + 1, number_of_pairs + 1):
            if edges[i - 1].first > edges[j - 1].second:
                start_time = edges[i - 1].second + 1
            else:
                temp = dp[i - 1][j - 1] + 1 if start_time == 0 else dp[i - 1][j - 1] + 1 + end_time - start_time
                end_time = edges[j - 1].second + 1
                dp[i][j] = max(temp, dp[i][j])

    return dp[number_of_pairs][number_of_pairs]
