    def calculate_average(path):
        return sum(path) / len(path)

    # Initialize the maximum average to negative infinity
    max_avg = float('-inf')

    # Iterate over all possible starting points
    for i in range(n):
        for j in range(n):
            # Iterate over all possible end points
            for k in range(n):
                for l in range(n):
                    # Find all possible paths from start to end
                    path = []
                    found = False
                    for x in range(i, k):
                        for y in range(j, l):
                            path.append(matrix[x][y])
                            if found:
                                break
                        if found:
                            break
                    if found:
                        # Calculate the average of the path
                        avg = calculate_average(path)
                        # Update the maximum average if needed
                        if avg > max_avg:
                            max_avg = avg
    return max_avg
