    for i in range(n):
        for j in range(n):
            if (i, j) == (0,0) or (i, j) == (0, n-1) or (i, j) == (n-1,0) or (i, j) == (n-1,n-1):
                maxAverage[(i, j)] = matrix[i][j]
            else:
                maxAverage[(i, j)] = max(matrix[i][j], 
                                        max(maxAverage[(i-1, j)], 
                                            maxAverage[(i, j-1)]), 
                                        maxAverage[(i-1, j-1)])
    maxPathIncluding = maxAverage[(0,0)]
    maxPathNotIncluding = maxAverage[(0,0)]
    for i in range(1, n):
        maxPathIncluding = max(maxPathIncluding, maxPathNotIncluding + matrix[i][0])
        maxPathNotIncluding = max(maxPathNotIncluding, maxPathIncluding, maxAverage[(i-1, 0)])
    for j in range(1, n):
        maxPathIncluding = max(maxPathIncluding, maxPathNotIncluding + matrix[0][j])
        maxPathNotIncluding = max(maxPathNotIncluding, maxPathIncluding, maxAverage[(0, j-1)])
