from typing import List

def get_median(nums1: List[int], nums2: List[int], n: int) -> float:
    if n == 0:
        return None
    if n == 1:
        return nums1[0]

    med1, med2 = 0, 0
    p1, p2 = 0, 0

    for i in range(n):
        if p1 < n and p2 < n:
            if nums1[p1] <= nums2[p2]:
                med1 = nums1[p1]
                p1 += 1
            else:
                med1 = nums2[p2]
                p2 += 1
        elif p1 < n:
            med1 = nums1[p1]
            p1 += 1
        else:
            med1 = nums2[p2]
            p2 += 1

        if i % 2 == n - 1:
            return med1
    return (med1 + med2) / 2
```

