def get_median(nums1, nums2, n):
    total = n
    index1, index2, count = 0, 0, 0
    median1, median2 = 0, 0
    while count < total:
        if index1 < n and index2 < n:
            if nums1[index1] < nums2[index2]:
                median1 = nums1[index1]
                index1 += 1
            else:
                median1 = nums2[index2]
                index2 += 1
        elif index1 < n:
            median1 = nums1[index1]
            index1 += 1
        else:
            median1 = nums2[index2]
            index2 += 1
        count += 1
    if total % 2 == 1:
        return median1
    else:
        return (median1 + median2) / 2
