def remove_similar_row(matrix):
    row_dict = {}
    rows_to_remove = []
    for row in matrix:
        # Convert the tuple to a string to facilitate lookup
        row_key = frozenset(row)
        if row_key in row_dict:
            rows_to_remove += [row_dict[row_key], row]
        else:
            row_dict[row_key] = row
    # Remove the duplicate rows
    for row in rows_to_remove:
        matrix.remove(row)
    return {tuple(row) for row in matrix}
```

