def max_sum_increasing_subsequence(array, length):
    if not array or length == 0:
        return 0

    # Initialize the maximum sum array with the first element
    max_sum = [array[0]] * length

    # Iterate through the array starting from the second element
    for i in range(1, length):
        # Initialize maximum ending at 'i' as the current element
        max_ending_at_i = array[i]
        # Iterate through all previous elements to find the maximum ending at 'i'
        for j in range(i):
            if array[j] < array[i] and max_ending_at_i < max_sum[j] + array[i]:
                max_ending_at_i = max_sum[j] + array[i]

        # Update the maximum sum array with the maximum ending at 'i'
        max_sum[i] = max_ending_at_i

    # The largest element in the maximum sum array is the maximum increasing subsequence sum
    return max(max_sum)
```

