        if time in departing_days:
            departing_days[time] += 1
        else:
            departing_days[time] = 1

    # Calculate the minimum number of platforms required
    min_platforms = 0
    max_platforms = 0

    for _, count in arriving_days.items():
        min_platforms = max(count, min_platforms)

    for _, count in departing_days.items():
        max_platforms = max(count, max_platforms)

    min_platforms += len(arriving_times) - max_platforms

    return min_platforms
