def dealnnoy_num(n, k):
    # Initialize the base case
    if k == 0:
        return 1
    # Initialize the dp table
    dp = [[0 for _ in range(n + 1)] for _ in range(k + 1)]
    # Fill the dp table
    for i in range(k + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1] + dp[i-1][j-1]
    return dp[k][n]
```

