    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif k == 0:
        return 1

    # Calculate the nth Delannoy number
    delnnoy = 0
    for i in range(k + 1):
        delnnoy += dealnnoy_num(n - i, k)
    return delnnoy
