def min_cost(cost, m, n):
    # Initialize a 2D array to store the minimum cost at each position
    dp = [[float('inf')] * (n+1) for _ in range(m+1)]

    # Base case: the cost to reach (0, 0) is 0
    dp[0][0] = 0

    # Fill the dp array
    for i in range(m+1):
        for j in range(n+1):
            # If we are at the first row
            if i == 0:
                dp[i][j] = dp[i][j-1] + cost[i][j-1]
            # If we are at the first column
            elif j == 0:
                dp[i][j] = dp[i-1][j] + cost[i-1][j]
            # Otherwise, the minimum cost is the minimum of the cost to reach the cell above, to the left, and the diagonal left
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + cost[i][j]

    return dp[m][n]  # Return the minimum cost to reach (m, n)
