def radix_sort(nums):
    if not nums:
        return []
    max_digit = max(int(num) for num in nums)
    for digit in range(0, max_digit + 1):
        buckets = [[] for _ in range(10)]
        for num in nums:
            bucket[int(num // (10 ** digit)) % 10].append(num)
        nums = []
        for bucket in buckets:
            nums.extend(bucket)
    return nums
```

