def count_Rotation(arr, n):
    start = 0
    end = n - 1

    while start < end:
        mid = start + (end - start) // 2
        next = (mid + 1) % n
        prev = (mid - 1 + n) % n

        if arr[mid] <= arr[next] and arr[mid] <= arr[prev]:
            return mid
        elif arr[mid] <= arr[end]:
            end = mid
        else:
            start = mid + 1

    return -1
```

