def find_Min_Swaps(arr, n):
    min_swaps = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                count = 0
                arr[i], arr[j] = arr[j], arr[i]
                for k in range(i + 1, n):
                    if arr[k] == 0:
                        count += 1
                min_swaps = min(min_swaps, count)
                arr[i], arr[j] = arr[j], arr[i]  # Reset the array for next inner loop
    return min_swaps
