def find_Min_Swaps(arr, n):
    swaps = 0
    for i in range(n-1):
        # Find the next 0
        min_index = i+1
        for j in range(i+2, n):
            if arr[j] == 0:
                min_index = j
                break
        # Swap with the next 1
        for j in range(min_index, n):
            if arr[j] == 1:
                arr[min_index], arr[j] = arr[j], arr[min_index]
                swaps += 1
                break
    return swaps
