def rgb_to_hsv(r, g, b):
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    diff = max_color - min_color
    value = max_color / 255.0

    if value == 0:
        saturation = 0
    else:
        saturation = diff / value

    if max_color == r:
        hue = ((g - b) / diff) % 6
    elif max_color == g:
        hue = ((b - r) / diff) + 2
    else:
        hue = ((r - g) / diff) + 4

    hue /= 6
    return hue, saturation, value
```

