def find_triplet_array(arr, n, target):
    arr.sort()
    for i in range(n-2):
        left, right = i + 1, n - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == target:
                return (arr[i], arr[left], arr[right])
            elif total < target:
                left += 1
            else:
                right -= 1
    return None
```

