def max_sum_of_three_consecutive(arr, n):
    dp = [0] * n
    if n < 3:
        return sum(arr)
    dp[0] = arr[0]
    dp[1] = arr[0] + arr[1]
    dp[2] = max(arr[0] + arr[2], arr[1] + arr[2])
    for i in range(3, n):
        dp[i] = max(dp[i-1], dp[i-2] + arr[i], dp[i-3] + arr[i] + arr[i-1])
    return dp[-1]
```

