        if arr[i] < arr[i - 1]:
            return False
    # Check if the array can be sorted with the corner elements
    arr[0], arr[n - 1] = arr[n - 1], arr[0]  # Swap the first and last elements
    if arr == sorted(arr):
        arr[0], arr[n - 1] = arr[n - 1], arr[0]  # Swap the first and last elements back
        return True
    else:
        arr[0], arr[n - 1] = arr[n - 1], arr[0]  # Swap the first and last elements back
        return False
