def lbs(arr):
    n = len(arr)
    # Find the length of the longest increasing subsequence (LIS)
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Find the length of the longest decreasing subsequence (LDS)
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # Find the length of the longest bitonic subsequence
    lbs = [lis[i] + lds[i] - 1 for i in range(n)]
    return max(lbs)
