def Hamming_Distance(x, y):
    distance = 0
    while x > 0 and y > 0:
        if x % 2 != y % 2:
            distance += 1
        x //= 2
        y //= 2
    while x > 0:
        if x % 2 != 0:
            distance += 1
        x //= 2
    while y > 0:
        if y % 2 != 0:
            distance += 1
        y //= 2
    return distance
