def maximum_segments(n, a, b, c):
    max_segments = 0
    max_a = n // a
    max_b = n // b
    max_c = n // c

    for i in range(max_a + 1):
        for j in range(max_b + 1):
            k = n - (i * a + j * b)
            if k % c == 0:
                max_segments += 1
    return max_segments
```

