def maximum_segments(n, a, b, c):
    # Sort the lengths of the segment types
    lengths = sorted([a, b, c])
    max_segments = 0

    # Iterate through all possible combinations of segment types
    for i in range(1, lengths[0] + 1):
        for j in range(1, lengths[1] + 1):
            for k in range(1, lengths[2] + 1):
                # Check if the sum of segments of type a, b, and c is less than or equal to n
                if i + j + k <= n:
                    max_segments += 1

    return max_segments
```

