def modular_sum(arr, n, m):
    # If sum is 0, we can have a subset with sum divisible by m
    if m == 0:
        return True
    # If the length of the array is 0, we can't have a subset with sum divisible by m
    if n == 0:
        return False
    # If the last element is greater than m, we can't include it in the subset
    if arr[n-1] > m:
        return modular_sum(arr, n-1, m)
    # Check if it's possible to make a sum divisible by m with the remaining array and last element
    return modular_sum(arr, n-1, m) or modular_sum(arr, n-1, m-arr[n-1])
```

