    if total_sum % m != 0:
        return False
    else:
        # Check if any subset with sum divisible by m exists
        dp = [False] * (total_sum // m + 1)
        dp[0] = True
        for num in arr:
            for i in range(total_sum // m, num - 1, -1):
                dp[i] = dp[i] or dp[i - num]
        return dp[total_sum // m]
