def modular_sum(arr, n, m):
    # Initialize a 2D array to store intermediate results
    dp = [[False for _ in range(m + 1)] for _ in range(n + 1)]

    # Base case: There is a subset with sum 0 (for any m)
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if arr[i - 1] <= j:
                dp[i][j] = (dp[i - 1][j] or dp[i - 1][j - arr[i - 1]])
            else:
                dp[i][j] = dp[i - 1][j]

    # Check if there is a subset with sum divisible by m
    return dp[n][m]
