def min_cost(cost, m, n):
    # Create a 2D list to store the minimum cost to reach each cell
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]

    # Base case: the minimum cost to reach (0, 0) is the value in the starting cell
    dp[0][0] = cost[0][0]

    # Fill the dp table
    for i in range(m + 1):
        for j in range(n + 1):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + cost[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + cost[i][j])

    # The minimum cost to reach (m, n) is stored in dp[m][n]
    return dp[m][n]
```

