import math

def min_Jumps(d, x, y):
    if (d == x) and (y == 0):
        return 0
    for i in range(1, d+1):
        if (is_jump_possible(d, i, x, y)):
            return 1 + min_Jumps(d, (d-i), x, y)
    return float('inf')

def is_jump_possible(d, i, x, y):
    for j in range(y, 0, -1):
        if (d - i - j >= x):
            return True
    return False
