def coin_change(coins, m, n):
    dp = [[0 for _ in range(n+1)] for _ in range(m+1)]
    for i in range(n+1):
        dp[0][i] = i
    for i in range(1, m+1):
        for j in range(1, n+1):
            if coins[i-1] <= j:
                dp[i][j] = min(dp[i-1][j], 1 + dp[i][j-coins[i-1]])
            else:
                dp[i][j] = dp[i-1][j]
    return dp[m][n]
```

